from typing import Dict, Any

class Message:
    def __init__(self, id: str, body: Dict[str, Any], attributes: Dict[str, str] = None):
        self.id = id
        self.body = body
        self.attributes = attributes if attributes is not None else {}

    def to_dict(self):
        return {
            "id": self.id,
            "body": self.body,
            "attributes": self.attributes
        }

class PublishRequest:
    def __init__(self, event_data: Dict[str, Any], message_attributes: Dict[str, Any] = None):
        self.event_data = event_data
        self.message_attributes = message_attributes if message_attributes is not None else {}

class PublishResponse:
    def __init__(self, message_id: str):
        self.message_id = message_id

class ConsumeResponse:
    def __init__(self, messages: list[Message]):
        self.messages = messages

import boto3
from typing import Dict, Any

def get_sns_client(region_name: str):
    return boto3.client("sns", region_name=region_name)

def get_sqs_client(region_name: str):
    return boto3.client("sqs", region_name=region_name)

def create_sns_message_attributes(attributes: Dict[str, Any]):
    sns_attributes = {}
    for key, value in attributes.items():
        if isinstance(value, str):
            sns_attributes[key] = {'DataType': 'String', 'StringValue': value}
        elif isinstance(value, (int, float)):
            sns_attributes[key] = {'DataType': 'Number', 'StringValue': str(value)}
        # Add more types if needed, or handle complex objects by serializing to JSON string
    return sns_attributes

import boto3
from messaging_client import get_sqs_client

def configure_dead_letter_queue(
    queue_url: str,
    region_name: str,
    dead_letter_queue_arn: str,
    max_receive_count: int
):
    """
    Configures a dead-letter queue for the given SQS queue.
    This function modifies the attributes of an existing SQS queue.
    """
    sqs_client = get_sqs_client(region_name)

    redrive_policy = {
        "deadLetterTargetArn": dead_letter_queue_arn,
        "maxReceiveCount": str(max_receive_count)
    }

    sqs_client.set_queue_attributes(
        QueueUrl=queue_url,
        Attributes={
            'RedrivePolicy': json.dumps(redrive_policy)
        }
    )
    return {"status": "dead-letter queue configured", "queue_url": queue_url, "dead_letter_target_arn": dead_letter_queue_arn}

def get_queue_arn(queue_url: str, region_name: str) -> str:
    sqs_client = get_sqs_client(region_name)
    response = sqs_client.get_queue_attributes(
        QueueUrl=queue_url,
        AttributeNames=['QueueArn']
    )
    return response['Attributes']['QueueArn']

